import org.jlinalg.study.StudyOperationExecutor.Context;

/** Positive LD evidence constrains redundant manuscript slots without changing statistical eligibility. */
final class StudyFindingGrouping {
    static final String CAVEAT="Registered LD components describe transitive positive linkage evidence in the declared reference populations and edge window. They are not P-ranked index-variant clumps, fine-mapped causal signals, proof of one mechanism, or proof that different components are independent. Chains can span more than the edge window, and component members need not all meet the pairwise r-squared cutoff. Shared variant identities and positive edges across reference populations are conservatively combined, not treated as independent replication. Coverage/calibration and ancestry applicability require source review; missing variants or pairs are not evidence of zero LD.";
    record Outcome(Map<String,Object> summary,List<String> outputs,Map<String,Map<String,Object>> assignments) { }
    private record Reference(Map<String,Object> declaration,Map<String,StudyVariantUniverse.Key> aliases,Set<String> variants,String sourceId,boolean complete) { }
    private static final class Graph {
        final Map<String,String> parent=new TreeMap<>();
        void add(String key){parent.putIfAbsent(key,key);}
        String root(String key){String p=parent.get(key);if(p==null)throw new IllegalArgumentException("Unknown LD graph node");String r=p;while(!r.equals(parent.get(r)))r=parent.get(r);while(!p.equals(r)){parent.put(key,r);key=p;p=parent.get(key);}return r;}
        void union(String a,String b){a=root(a);b=root(b);if(a.compareTo(b)>0){String t=a;a=b;b=t;}if(!a.equals(b))parent.put(b,a);}
    }
    private StudyFindingGrouping() { }
    static Map<String,Object> policy(Context c){return StudyFindingGroupingPolicy.resolve(map(map(c.study().get("project")).get("finding_grouping")));}
    static Outcome apply(Context c,Map<String,Map<String,Object>> findings,Map<String,List<Object>> observations,Map<String,Map<String,Object>> declared,Map<String,Map<String,Object>> sources,Map<String,StudyPrimaryResults.Selection> primary)throws IOException {
        var p=policy(c);var summary=new LinkedHashMap<String,Object>();summary.put("configured",!list(p.get("references")).isEmpty());summary.put("complete",true);summary.put("performed",false);summary.put("required_manuscript_caveat",CAVEAT);summary.put("minimum_r_squared",p.get("minimum_r_squared"));summary.put("maximum_distance_bp",p.get("maximum_distance_bp"));var assignments=new TreeMap<String,Map<String,Object>>();var directory=c.outputDirectory().resolve("finding-grouping");Files.createDirectories(directory);
        if(!Boolean.TRUE.equals(p.get("enabled"))||list(p.get("references")).isEmpty()){summary.put("status",Boolean.TRUE.equals(p.get("enabled"))?"no_registered_ld_reference":"disabled_by_protocol");return finish(c,directory,summary,assignments);}
        var graph=new Graph();var refs=new ArrayList<Reference>();var problems=new ArrayList<String>();var nodeSources=new TreeMap<String,Set<String>>();var edges=new ArrayList<String[]>();long[] work={0,0};
        for(Object raw:activeReferences(c.study(),p)){var r=map(raw);try{refs.add(read(c,directory,p,r,graph,nodeSources,edges,sources,work));}catch(IOException|IllegalArgumentException invalid){problems.add("Reference "+r.get("id")+": "+String.valueOf(invalid.getMessage()));}}
        var byHypothesis=new TreeMap<String,Reference>();for(var r:refs)for(Object h:list(r.declaration.get("hypotheses")))byHypothesis.put(text(h),r);var matched=new TreeMap<String,StudyVariantUniverse.Key>();var dispositions=new ArrayList<String[]>();int candidates=0,unmapped=0;
        for(var entry:findings.entrySet()){
            var finding=entry.getValue();String h=text(finding.get("hypothesis")),feature=text(finding.get("feature_id"));var rows=observations.getOrDefault(entry.getKey(),List.of());boolean variant=variantFinding(c,h,feature,rows,primary.get(h));boolean eligible=Boolean.TRUE.equals(finding.get("estimable"))&&(Boolean.TRUE.equals(finding.get("significant"))||Boolean.TRUE.equals(declared.getOrDefault(entry.getKey(),Map.of()).get("include_null")));String status="not_a_primary_single_variant_finding";String canonical="";Reference reference=byHypothesis.get(h);
            if(variant){if(eligible)candidates++;if(reference==null){status="reference_not_registered_for_hypothesis";if(eligible)unmapped++;}else{try{var key=alias(reference,feature);if(key==null){status="variant_not_in_reference";if(eligible)unmapped++;}else{identity(c,h,key,rows,primary.get(h),reference);matched.put(entry.getKey(),key);canonical=key.id();status="reference_variant_matched";}}catch(IOException invalid){status="analysis_identity_conflict";problems.add(h+"/"+feature+": "+invalid.getMessage());}}}
            dispositions.add(new String[]{text(finding.get("finding_id")),h,feature,String.valueOf(eligible),status,canonical,reference==null?"":text(reference.declaration.get("id"))});
        }
        if(Boolean.TRUE.equals(p.get("require_complete_coverage"))&&unmapped>0)problems.add(unmapped+" eligible single-variant findings lack a registered allele-resolved LD reference; absent variants are not independent signals");
        if(Boolean.TRUE.equals(p.get("require_complete_coverage"))&&refs.stream().anyMatch(r->!r.complete))problems.add("At least one LD export cannot establish the registered edge-window/cutoff coverage; incomplete pairs are not zero LD");
        FollowupSupport.table(directory.resolve("variant-dispositions.tsv"),List.of("finding_id","hypothesis","feature_id","eligible","status","canonical_variant","reference_id"),dispositions);FollowupSupport.table(directory.resolve("pair-dispositions.tsv"),List.of("reference_id","variant_a","variant_b","r_squared","distance_bp","disposition"),edges);
        summary.put("reference_count",refs.size());summary.put("reference_variant_rows",work[0]);summary.put("reference_pair_rows",work[1]);summary.put("eligible_variant_findings",candidates);summary.put("unmatched_eligible_variant_findings",unmapped);summary.put("configured_reference_count",list(p.get("references")).size());summary.put("active_reference_count",activeReferences(c.study(),p).size());summary.put("all_declared_reference_scopes_complete",refs.size()==activeReferences(c.study(),p).size()&&refs.stream().allMatch(Reference::complete));summary.put("problems",problems);
        if(!problems.isEmpty()){summary.put("complete",false);summary.put("status","registered_grouping_unavailable");String reason=String.join("; ",problems);summary.put("needs",List.of(StudyNeed.review("finding-grouping:"+StudyFindingInventory.hash(reason).substring(0,20),"Resolve the registered finding LD evidence",reason,true).document()));return finish(c,directory,summary,assignments);}
        var members=new TreeMap<String,Set<String>>();for(String node:graph.parent.keySet())members.computeIfAbsent(graph.root(node),ignored->new TreeSet<>()).add(node);var componentSources=new TreeMap<String,Set<String>>();var componentIds=new TreeMap<String,String>();
        for(var component:members.entrySet()){var ids=new TreeSet<String>();for(String node:component.getValue())ids.addAll(nodeSources.getOrDefault(node,Set.of()));componentSources.put(component.getKey(),ids);componentIds.put(component.getKey(),"ld-component:"+StudyFindingInventory.hash(StudyAssistance.json(Map.of("variants",component.getValue(),"minimum_r_squared",p.get("minimum_r_squared"),"maximum_edge_distance_bp",p.get("maximum_distance_bp")))).substring(0,32));}
        var membership=new ArrayList<String[]>();var findingCounts=new TreeMap<String,Integer>();
        for(var entry:matched.entrySet()){String root=graph.root(entry.getValue().id()),component=componentIds.get(root);var finding=findings.get(entry.getKey());var sourceIds=List.copyOf(componentSources.get(root));var grouping=new LinkedHashMap<String,Object>();grouping.put("status","registered_ld_component");grouping.put("component_id",component);grouping.put("canonical_variant",entry.getValue().id());grouping.put("reference_variant_members",members.get(root).size());grouping.put("source_ids",sourceIds);grouping.put("minimum_r_squared",p.get("minimum_r_squared"));grouping.put("maximum_edge_distance_bp",p.get("maximum_distance_bp"));grouping.put("required_manuscript_caveat",CAVEAT);assignments.put(entry.getKey(),grouping);findingCounts.merge(root,1,Integer::sum);membership.add(new String[]{text(finding.get("finding_id")),text(finding.get("hypothesis")),text(finding.get("feature_id")),entry.getValue().id(),component,String.valueOf(members.get(root).size()),String.join(";",sourceIds)});}
        FollowupSupport.table(directory.resolve("finding-membership.tsv"),List.of("finding_id","hypothesis","feature_id","canonical_variant","redundancy_group","reference_variant_members","source_ids"),membership);var components=new ArrayList<String[]>();for(var entry:findingCounts.entrySet())components.add(new String[]{componentIds.get(entry.getKey()),String.valueOf(entry.getValue()),String.valueOf(members.get(entry.getKey()).size()),String.join(";",componentSources.get(entry.getKey()))});FollowupSupport.table(directory.resolve("components.tsv"),List.of("redundancy_group","inventory_findings","reference_variant_members","source_ids"),components);
        summary.put("performed",true);summary.put("status",unmapped==0&&refs.stream().allMatch(Reference::complete)?"registered_observed_components":"descriptive_partial_reference_components");summary.put("matched_inventory_findings",matched.size());summary.put("components_with_findings",components.size());summary.put("association_results_modified",false);summary.put("story_group_labels_modified",false);return finish(c,directory,summary,assignments);
    }
    static List<Map<String,Object>> activeReferences(Map<String,Object> study,Map<String,Object> policy){var active=new TreeSet<String>();for(Object raw:list(study.get("hypotheses"))){var h=map(raw);if(!"retired".equals(h.get("status")))active.add(text(h.get("id")));}return list(policy.get("references")).stream().map(StudyPublicEvidence::map).filter(r->list(r.get("hypotheses")).stream().anyMatch(active::contains)).toList();}
    private static Reference read(Context c,Path directory,Map<String,Object> p,Map<String,Object> r,Graph graph,Map<String,Set<String>> nodeSources,List<String[]> dispositions,Map<String,Map<String,Object>> sources,long[] work)throws IOException {
        String id=text(r.get("id")),build=text(r.get("genome_build"));Path output=directory.resolve(id);Files.createDirectories(output);var hashes=new LinkedHashMap<String,String>();var files=new LinkedHashMap<String,Path>();
        for(String role:List.of("variants","pairs")){Path source=c.project().resolve(text(r.get(role))).normalize();if(!Files.isRegularFile(source))throw new IOException("Missing registered "+role+" file");String hash=FollowupSupport.hash(source);Path copy=output.resolve(role+".tsv"+(source.getFileName().toString().endsWith(".gz")?".gz":""));Files.copy(source,copy);if(!hash.equals(FollowupSupport.hash(copy))||!hash.equals(FollowupSupport.hash(source)))throw new IOException("Grouping input changed during its immutable snapshot");hashes.put(role,hash);files.put(role,copy);}
        var table=DelimitedData.readResult(files.get("variants"));for(String column:List.of("variant_id","chromosome","position","ref","alt"))table.column(column);work[0]+=table.rows().size();if(work[0]>integer(p,"maximum_variants"))throw new IOException("Complete LD variant catalog exceeds maximum_variants; no top findings were selected");var aliases=new TreeMap<String,StudyVariantUniverse.Key>();var keys=new TreeMap<String,StudyVariantUniverse.Key>();
        for(String[] row:table.rows()){String name=label(row[table.column("variant_id")]);if(table.header().contains("genome_build")&&!StudyVariantUniverse.build(row[table.column("genome_build")]).equals(build))throw new IOException("LD variant build conflicts with its reference scope");long position;try{position=Long.parseLong(row[table.column("position")]);}catch(NumberFormatException invalid){throw new IOException("Invalid LD variant position",invalid);}var key=StudyVariantUniverse.key(build,row[table.column("chromosome")],position,row[table.column("ref")],row[table.column("alt")]);if(key==null)throw new IOException("LD variants need canonical positive coordinates and distinct DNA alleles");var named=StudyVariantUniverse.parseId(name,build);if(named!=null&&!named.equals(key))throw new IOException("LD variant name conflicts with coordinates/alleles");var old=aliases.putIfAbsent(name,key);if(old!=null&&!old.equals(key))throw new IOException("Conflicting LD variant alias");keys.put(key.id(),key);graph.add(key.id());}
        var input=DelimitedData.readResult(files.get("pairs"));for(String column:List.of("variant_a","variant_b","r_squared"))input.column(column);work[1]+=input.rows().size();if(work[1]>integer(p,"maximum_pairs"))throw new IOException("Complete LD export exceeds maximum_pairs; no successful pair subset was published");var observed=new TreeMap<String,Double>();double cutoff=((Number)p.get("minimum_r_squared")).doubleValue();long radius=((Number)p.get("maximum_distance_bp")).longValue();
        for(String[] row:input.rows()){var a=resolve(aliases,keys,row[input.column("variant_a")],build);var b=resolve(aliases,keys,row[input.column("variant_b")],build);if(a==null||b==null)throw new IOException("LD pair references a variant absent from the explicit catalog");String rawValue=row[input.column("r_squared")];boolean missing=Set.of("","NA","NaN",".").contains(rawValue);double value;try{value=missing?Double.NaN:Double.parseDouble(rawValue);}catch(NumberFormatException invalid){throw new IOException("Malformed LD r_squared",invalid);}if(!missing&&(!Double.isFinite(value)||value<0||value>1||a.equals(b)&&Math.abs(value-1)>1e-12))throw new IOException("Invalid LD r_squared or self-pair");String pair=pair(a.id(),b.id());var old=observed.putIfAbsent(pair,value);if(old!=null&&Double.compare(old,value)!=0)throw new IOException("Conflicting duplicate undirected LD pair");long distance=a.chromosome().equals(b.chromosome())?Math.abs(a.position()-b.position()):Long.MAX_VALUE;boolean selected=Double.isFinite(value)&&!a.equals(b)&&distance<=radius&&value>=cutoff;if(selected)graph.union(a.id(),b.id());dispositions.add(new String[]{id,a.id(),b.id(),String.valueOf(value),distance==Long.MAX_VALUE?"NA":String.valueOf(distance),missing?"unavailable_ld_not_zero":a.equals(b)?"self_pair":distance>radius?"outside_registered_edge_window":value<cutoff?"below_registered_r_squared":"positive_ld_link"});}
        boolean complete=false;String coverage=text(r.get("coverage"));long window=r.get("window_bp") instanceof Number n?n.longValue():-1;
        if(coverage.equals("complete_window")&&window>=radius){long comparisons=0;var ordered=keys.values().stream().sorted(Comparator.comparing(StudyVariantUniverse.Key::chromosome).thenComparingLong(StudyVariantUniverse.Key::position).thenComparing(StudyVariantUniverse.Key::id)).toList();complete=true;for(int a=0;a<ordered.size();a++)for(int b=a+1;b<ordered.size();b++){var x=ordered.get(a);var y=ordered.get(b);if(!x.chromosome().equals(y.chromosome())||y.position()-x.position()>radius)break;if(++comparisons>integer(p,"maximum_pairs"))throw new IOException("Complete window-pair verification exceeds maximum_pairs");if(!Double.isFinite(observed.getOrDefault(pair(x.id(),y.id()),Double.NaN)))complete=false;}}
        if(coverage.equals("thresholded_window")&&window>=radius&&r.get("minimum_reported_r_squared") instanceof Number n){double threshold=n.doubleValue();complete=threshold<cutoff||threshold==cutoff&&"greater_than_or_equal".equals(r.get("reporting_comparison"));}
        long unknownWindowPairs=0;for(var pairEntry:observed.entrySet())if(!Double.isFinite(pairEntry.getValue())){String[] ids=pairEntry.getKey().split("\u001f",-1);var a=keys.get(ids[0]);var b=keys.get(ids[1]);if(!a.equals(b)&&a.chromosome().equals(b.chromosome())&&Math.abs(a.position()-b.position())<=radius)unknownWindowPairs++;}if(unknownWindowPairs>0)complete=false;
        String sourceId="source-ld-"+StudyFindingInventory.hash(StudyAssistance.json(Map.of("reference",r,"input_sha256",hashes))).substring(0,24);var receipt=new LinkedHashMap<String,Object>();for(String field:List.of("id","genome_build","population","release","hypotheses","coverage","window_bp","minimum_reported_r_squared","reporting_comparison","rationale"))if(r.containsKey(field))receipt.put(field,r.get(field));receipt.put("input_sha256",hashes);receipt.put("catalog_variants",keys.size());receipt.put("observed_undirected_pairs",observed.size());receipt.put("unavailable_pairs_within_grouping_window",unknownWindowPairs);receipt.put("grouping_window_coverage_available",complete);receipt.put("coverage_assessment",coverage.equals("complete_window")?"Observed pair coverage checked within the registered analysis window and supplied catalog only":"Source-declared threshold/window completeness; not independently reproduced from participant genotypes");receipt.put("required_manuscript_caveat",CAVEAT);write(output.resolve("reference.yaml"),receipt);
        sources.put(sourceId,Map.of("operation_id",c.operation().get("id"),"operation_type","finding_ld_reference","hypothesis","__study__","artifact",c.project().relativize(output.resolve("reference.yaml")).toString().replace('\\','/'),"sha256",FollowupSupport.hash(output.resolve("reference.yaml")),"reference",receipt));for(String key:keys.keySet())nodeSources.computeIfAbsent(key,ignored->new TreeSet<>()).add(sourceId);return new Reference(r,aliases,keys.keySet(),sourceId,complete);
    }
    private static StudyVariantUniverse.Key alias(Reference r,String feature)throws IOException {var key=r.aliases.get(feature);if(key!=null)return key;var named=StudyVariantUniverse.parseId(feature,text(r.declaration.get("genome_build")));return named!=null&&r.variants.contains(named.id())?named:null;}
    private static StudyVariantUniverse.Key resolve(Map<String,StudyVariantUniverse.Key> aliases,Map<String,StudyVariantUniverse.Key> keys,String value,String build)throws IOException {var known=aliases.get(value);if(known!=null)return known;var named=StudyVariantUniverse.parseId(value,build);return named==null?null:keys.get(named.id());}
    private static boolean variantFinding(Context c,String h,String feature,List<Object> rows,StudyPrimaryResults.Selection selected) {
        if(rows.stream().map(StudyPublicEvidence::map).noneMatch(r->Boolean.TRUE.equals(r.get("primary"))&&Set.of("association","meta_analysis","validate_harmonize").contains(text(r.get("operation_type")))))return false;
        if(selected!=null&&Set.of("gwas","genomics").contains(text(map(map(selected.source().producer().manifest().get("details")).get("scope")).get("modality"))))return true;
        var ids=new LinkedHashSet<String>();for(Object raw:list(c.study().get("hypotheses"))){var hypothesis=map(raw);if(h.equals(hypothesis.get("id")))map(hypothesis.get("inputs")).values().forEach(v->list(v).forEach(id->ids.add(text(id))));}var types=new TreeSet<String>();for(Object raw:list(c.study().get("datasets"))){var d=map(raw);if(ids.contains(text(d.get("id")))&&!Set.of("set_association_results","rare_score_summary").contains(text(d.get("stage"))))types.add(text(d.get("type")));}return !types.isEmpty()&&types.stream().allMatch(t->Set.of("gwas","genomics").contains(t));
    }
    private static void identity(Context c,String h,StudyVariantUniverse.Key key,List<Object> rows,StudyPrimaryResults.Selection selected,Reference reference)throws IOException {
        if(selected!=null)compatibleScope(map(map(selected.source().producer().manifest().get("details")).get("scope")),reference);
        for(Object raw:list(c.study().get("hypotheses"))){var hypothesis=map(raw);if(h.equals(hypothesis.get("id")))compatibleScope(hypothesis,reference);}
        if(selected!=null){var scope=map(map(selected.source().producer().manifest().get("details")).get("scope"));String build=text(scope.get("genome_build"));if(!build.isBlank()&&!StudyVariantUniverse.build(build).equals(key.build()))throw new IOException("Primary source build differs from the LD reference");}
        for(Object raw:rows){var row=map(raw);if(!Boolean.TRUE.equals(row.get("primary")))continue;String build=text(row.get("genome_build"));if(!build.isBlank()&&!StudyVariantUniverse.build(build).equals(key.build()))throw new IOException("Primary variant build differs from the reference");String chromosome=text(row.get("chromosome"));if(!chromosome.isBlank()&&!chromosome.replaceFirst("(?i)^chr","").equals(key.chromosome()))throw new IOException("Primary variant chromosome differs from the reference");if(row.containsKey("position")&&StudyCohortResults.numeric(text(row.get("position")))!=key.position())throw new IOException("Primary variant position differs from the reference");String ref=text(row.get("reference_allele")),alt=text(row.get("alternate_allele"));if(!ref.isBlank()&&!alt.isBlank()&&(!ref.equalsIgnoreCase(key.reference())||!alt.equalsIgnoreCase(key.alternate())))throw new IOException("Primary variant REF/ALT identity differs from the reference");String effect=text(row.get("effect_allele")),other=text(row.get("other_allele"));if(!effect.isBlank()&&!other.isBlank()&&!new TreeSet<>(List.of(effect.toUpperCase(java.util.Locale.ROOT),other.toUpperCase(java.util.Locale.ROOT))).equals(Set.of(key.reference(),key.alternate())))throw new IOException("Primary effect alleles do not match the reference variant");}
        // A registered external primary carries its own scope; unused raw inputs are not its producers.
        if(selected!=null&&"externally_produced".equals(map(selected.source().producer().manifest().get("details")).get("execution_origin")))return;
        var ids=new TreeSet<String>();for(Object raw:list(c.study().get("hypotheses"))){var d=map(raw);if(h.equals(d.get("id")))map(d.get("inputs")).values().forEach(v->list(v).forEach(id->ids.add(text(id))));}for(Object raw:list(c.study().get("datasets"))){var d=map(raw);if(!ids.contains(text(d.get("id")))||!Set.of("gwas","genomics").contains(text(d.get("type"))))continue;compatibleScope(d,reference);compatibleScope(map(d.get("metadata")),reference);for(Object rawCohort:list(c.study().get("cohorts"))){var cohort=map(rawCohort);if(text(d.get("cohort")).equals(cohort.get("id")))compatibleScope(cohort,reference);}String build=text(d.get("genome_build"));if(!build.isBlank()&&!StudyVariantUniverse.build(build).equals(key.build()))throw new IOException("Declared GWAS dataset build differs from the LD reference");}
    }
    private static void compatibleScope(Map<String,Object> scope,Reference reference)throws IOException {
        String species=text(scope.get("species"));if(!species.isBlank()&&!StudyPoolingAudit.canonical("species",species).equals("9606"))throw new IOException("Human assembly LD cannot group a known nonhuman source");
        String expected=population(text(reference.declaration.get("population")));for(String key:List.of("population","ancestry")){String observed=population(text(scope.get(key)));if(!expected.isBlank()&&!observed.isBlank()&&!expected.equals(observed))throw new IOException("Known source ancestry/population differs from the registered LD reference");}
    }
    private static String population(String value){return switch(value.strip().toUpperCase(java.util.Locale.ROOT).replace(' ','_').replace('-','_')){case "EUR","EUROPEAN","EUROPEAN_ANCESTRY"->"EUR";case "AFR","AFRICAN","AFRICAN_ANCESTRY"->"AFR";case "EAS","EAST_ASIAN"->"EAS";case "SAS","SOUTH_ASIAN"->"SAS";case "AMR","ADMIXED_AMERICAN"->"AMR";default->"";};}
    static void distinct(List<Map<String,Object>> findings)throws IllegalArgumentException {var stories=new LinkedHashSet<String>();var redundancy=new LinkedHashSet<String>();for(var finding:findings){if(!stories.add(text(finding.get("story_group"))))throw new IllegalArgumentException("One story group cannot fill multiple principal-finding slots");for(Object raw:list(finding.get("redundancy_groups")))if(!redundancy.add(text(raw)))throw new IllegalArgumentException("Principal-finding slots share a registered LD redundancy component; different labels or genes do not establish distinct signals");}}
    private static Outcome finish(Context c,Path directory,Map<String,Object> summary,Map<String,Map<String,Object>> assignments)throws IOException {write(directory.resolve("grouping.yaml"),summary);var outputs=new ArrayList<String>();try(var paths=Files.walk(directory)){for(Path p:paths.filter(Files::isRegularFile).sorted().toList())outputs.add(c.outputDirectory().relativize(p).toString().replace('\\','/'));}return new Outcome(summary,outputs,assignments);}
    private static String label(String value)throws IOException {if(value.isBlank()||value.length()>1000||value.chars().anyMatch(Character::isISOControl))throw new IOException("Invalid bounded LD variant identifier");return value;}
    private static String pair(String a,String b){return a.compareTo(b)<0?a+"\u001f"+b:b+"\u001f"+a;}
    private static int integer(Map<String,Object> p,String key){return ((Number)p.get(key)).intValue();}
}
